// Token generator (decisions 0003 and 0006 items 6 and 7). No dependencies.
//   node scripts/build.mjs   -> writes the generated files under src/ from tokens.json
// `generate()` is also used by scripts/check.mjs, which compares in memory and writes nothing.
// The output is deterministic (no clock, no environment) and already in the repository's
// Prettier style, so the pre-commit formatter leaves it unchanged.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const PACKAGE_DIR = join(dirname(fileURLToPath(import.meta.url)), '..');

const HEADER = 'Generated by scripts/build.mjs from tokens.json. Do not edit by hand.';
const CSS_PREFIX = 'kd';
const SOURCE_KEYS = [
  'color',
  'glass',
  'elevation',
  'space',
  'radius',
  'touchTarget',
  'font',
  'motion',
];

// PrimeUIX semantic token -> colour token, emitted as light-dark(<light>, <dark>), the form the
// Aura base of @primeuix/themes 3.1.0 uses. Every value comes from tokens.json; only the mapping
// lives here. Unmapped PrimeUIX tokens keep the Aura values (see README, "Gaps").
const PRIMENG_SEMANTIC_COLORS = {
  primary: {
    color: 'primary',
    contrastColor: 'onPrimary',
    hoverColor: 'primaryPressed',
    activeColor: 'primaryPressed',
  },
  highlight: {
    background: 'primaryContainer',
    color: 'onPrimaryContainer',
  },
  formField: {
    background: 'surface',
    disabledBackground: 'disabledBg',
    borderColor: 'outline',
    invalidBorderColor: 'error',
    color: 'text',
    disabledColor: 'disabledText',
    placeholderColor: 'textSecondary',
  },
  text: {
    color: 'text',
    mutedColor: 'textSecondary',
  },
  content: {
    background: 'surface',
    borderColor: 'divider',
  },
};
// PrimeUIX primitive border radius step -> radius token. The admin uses 8 and 12 only
// (style direction, admin section), so only sm and md are mapped.
const PRIMENG_RADIUS = { sm: 'sm', md: 'md' };

export function readTokens() {
  return JSON.parse(readFileSync(join(PACKAGE_DIR, 'tokens.json'), 'utf8'));
}

/** Returns a Map of package-relative path -> file content. */
export function generate(tokens) {
  validate(tokens);
  return new Map([
    ['src/tokens.css', cssFile(tokens)],
    ['src/index.ts', tokensModule(tokens)],
    ['src/primeng-preset.ts', primeNgModule(tokens)],
    ['src/react-native.ts', reactNativeModule(tokens)],
  ]);
}

// ---------------------------------------------------------------------------------------------
// Validation: fail loudly instead of emitting a partial theme.

function fail(message) {
  throw new Error(`tokens.json: ${message}`);
}

function validate(t) {
  for (const key of SOURCE_KEYS) if (!(key in t)) fail(`missing "${key}"`);
  const light = Object.keys(t.color.light ?? {});
  const dark = Object.keys(t.color.dark ?? {});
  if (light.length === 0) fail('color.light is empty');
  if (light.join() !== dark.join()) fail('color.light and color.dark must list the same keys');
  for (const mode of ['light', 'dark']) {
    if (!t.glass[mode]?.bg || !t.glass[mode]?.border) fail(`glass.${mode} needs bg and border`);
    if (typeof t.elevation[mode] !== 'string') fail(`elevation.${mode} must be a string`);
  }
  for (const group of Object.values(PRIMENG_SEMANTIC_COLORS)) {
    for (const name of Object.values(group)) {
      if (!light.includes(name)) fail(`color "${name}" used by the PrimeNG preset is missing`);
    }
  }
  for (const name of Object.values(PRIMENG_RADIUS)) {
    if (typeof t.radius[name] !== 'number') fail(`radius.${name} must be a number`);
  }
}

// ---------------------------------------------------------------------------------------------
// Value helpers

const kebab = (s) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

/** "20px" or "0" -> 20 / 0. Any other unit is an error: React Native takes plain numbers. */
function px(value, where) {
  const match = /^(-?\d+(?:\.\d+)?)(px)?$/.exec(String(value).trim());
  if (!match || (match[2] === undefined && Number(match[1]) !== 0)) {
    fail(`${where} must be a px length, got "${value}"`);
  }
  return Number(match[1]);
}

/** CSS box shadow "x y blur color" -> React Native boxShadow object; "none" -> null. */
function shadow(value, where) {
  if (value.trim() === 'none') return null;
  const match = /^(\S+)\s+(\S+)\s+(\S+)\s+(rgba?\([^)]*\)|#[0-9a-fA-F]{3,8})$/.exec(value.trim());
  if (!match) fail(`${where} must be one "x y blur color" shadow or "none", got "${value}"`);
  return {
    offsetX: px(match[1], where),
    offsetY: px(match[2], where),
    blurRadius: px(match[3], where),
    color: match[4],
  };
}

/** "'Be Vietnam Pro'" -> "Be Vietnam Pro". A stack is an error: React Native takes one family. */
function familyName(value) {
  const match = /^'([^',]+)'$|^"([^",]+)"$|^([^'",]+)$/.exec(value.trim());
  if (!match) fail(`font.family must be one family name, got "${value}"`);
  return (match[1] ?? match[2] ?? match[3]).trim();
}

// ---------------------------------------------------------------------------------------------
// TypeScript literal printer in the repository's Prettier style (single quotes, trailing commas,
// objects always expanded, short number arrays inline).

const IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

function str(value) {
  if (value.includes("'") && !value.includes('"')) return JSON.stringify(value);
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function literal(value, indent = '') {
  if (value === null) return 'null';
  if (typeof value === 'string') return str(value);
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) {
    if (!value.every((v) => typeof v === 'number')) fail('only number arrays are supported');
    return `[${value.join(', ')}]`;
  }
  const inner = `${indent}  `;
  const lines = Object.entries(value).map(([key, v]) => {
    if (!IDENTIFIER.test(key)) fail(`key "${key}" is not a plain identifier`);
    return `${inner}${key}: ${literal(v, inner)},`;
  });
  return `{\n${lines.join('\n')}\n${indent}}`;
}

const tsHeader = `// ${HEADER}\n`;
const tsConst = (name, value, suffix = ' as const', type = '') =>
  `export const ${name}${type ? `: ${type}` : ''} = ${literal(value)}${suffix};\n`;

// ---------------------------------------------------------------------------------------------
// (a) CSS custom properties, prefixed --kd-* (decision 0006 item 7; --p-* belongs to PrimeNG).
// Same selectors as the design workspace's tokens.css: light by default, dark through
// prefers-color-scheme unless data-theme="light", and data-theme="dark" forces dark.
// Hex colours are lowercased (CSS is case-insensitive) to match Prettier's CSS output.

function cssFile(t) {
  const v = (name) => `--${CSS_PREFIX}-${name}`;
  const schemeLines = (mode) => [
    ...Object.entries(t.color[mode]).map(([k, c]) => `${v(`color-${kebab(k)}`)}: ${c};`),
    `${v('glass-bg')}: ${t.glass[mode].bg};`,
    `${v('glass-border')}: ${t.glass[mode].border};`,
    `${v('elevation')}: ${t.elevation[mode]};`,
    `color-scheme: ${mode};`,
  ];
  const block = (selectors, lines, indent = '') =>
    [
      `${selectors.map((s) => indent + s).join(',\n')} {`,
      ...lines.map((l) => `${indent}  ${l}`),
      `${indent}}`,
    ].join('\n');

  const scaleLines = [`${v('glass-blur')}: ${t.glass.blur};`];
  t.space.forEach((s, i) => scaleLines.push(`${v(`space-${i + 1}`)}: ${s}px;`));
  for (const [k, r] of Object.entries(t.radius)) scaleLines.push(`${v(`radius-${k}`)}: ${r}px;`);
  scaleLines.push(`${v('touch-target')}: ${t.touchTarget}px;`);
  scaleLines.push(`${v('font-family')}: ${t.font.family}, ${t.font.fallback};`);
  for (const [group, scale] of [
    ['m', t.font.mobile],
    ['a', t.font.admin],
  ]) {
    for (const [k, s] of Object.entries(scale)) {
      scaleLines.push(`${v(`${group}-${kebab(k)}-size`)}: ${s.size}px;`);
      scaleLines.push(`${v(`${group}-${kebab(k)}-line`)}: ${s.line}px;`);
      scaleLines.push(`${v(`${group}-${kebab(k)}-weight`)}: ${s.weight};`);
    }
  }
  scaleLines.push(`${v('motion-fast')}: ${t.motion.fastMs}ms;`);
  scaleLines.push(`${v('motion-base')}: ${t.motion.baseMs}ms;`);

  const reduced = [
    `${v('motion-fast')}: ${t.motion.reducedMs}ms;`,
    `${v('motion-base')}: ${t.motion.reducedMs}ms;`,
  ];

  const css = [
    `/* ${HEADER} */`,
    block([':root', ":root[data-theme='light']", "[data-theme='light']"], schemeLines('light')),
    '',
    `@media (prefers-color-scheme: dark) {\n${block([":root:not([data-theme='light'])"], schemeLines('dark'), '  ')}\n}`,
    '',
    block([":root[data-theme='dark']", "[data-theme='dark']"], schemeLines('dark')),
    '',
    block([':root'], scaleLines),
    '',
    `@media (prefers-reduced-motion: reduce) {\n${block([':root'], reduced, '  ')}\n}`,
    '',
  ].join('\n');
  return css.replace(/#[0-9a-fA-F]{3,8}\b/g, (hex) => hex.toLowerCase());
}

// ---------------------------------------------------------------------------------------------
// (b) Typed tokens: every source token as a readonly literal.

function tokensModule(t) {
  const source = Object.fromEntries(SOURCE_KEYS.map((key) => [key, t[key]]));
  return [
    tsHeader,
    tsConst('tokens', source),
    'export type Tokens = typeof tokens;',
    "export type ColorScheme = keyof Tokens['color'];",
    "export type ColorToken = keyof Tokens['color']['light'];",
    '',
  ].join('\n');
}

// ---------------------------------------------------------------------------------------------
// (c) PrimeNG preset extension: a plain object in the PrimeUIX token shape, with no import, so the
// package stays a leaf (decision 0006 item 7). The admin passes it to `definePreset(Aura, ...)`.

function primeNgModule(t) {
  const semantic = { transitionDuration: `${t.motion.baseMs}ms` };
  for (const [group, entries] of Object.entries(PRIMENG_SEMANTIC_COLORS)) {
    semantic[group] = Object.fromEntries(
      Object.entries(entries).map(([key, name]) => [
        key,
        `light-dark(${t.color.light[name]}, ${t.color.dark[name]})`,
      ]),
    );
  }
  const borderRadius = Object.fromEntries(
    Object.entries(PRIMENG_RADIUS).map(([step, name]) => [step, `${t.radius[name]}px`]),
  );
  return [
    tsHeader,
    '// Extension for `definePreset(Aura, primeNgPreset)` from @primeuix/themes (see README).',
    tsConst('primeNgPreset', { primitive: { borderRadius }, semantic }),
  ].join('\n');
}

// ---------------------------------------------------------------------------------------------
// (d) React Native theme: plain numbers and colour strings, no CSS units.

function reactNativeModule(t) {
  const scheme = (mode) => ({
    dark: mode === 'dark',
    colors: t.color[mode],
    glass: {
      background: t.glass[mode].bg,
      border: t.glass[mode].border,
      blur: px(t.glass.blur, 'glass.blur'),
    },
    elevation: shadow(t.elevation[mode], `elevation.${mode}`),
  });
  const typography = Object.fromEntries(
    Object.entries(t.font.mobile).map(([k, s]) => [
      k,
      { fontSize: s.size, lineHeight: s.line, fontWeight: String(s.weight) },
    ]),
  );
  return [
    tsHeader,
    "import type { ColorToken } from './index.js';",
    '',
    'export interface Shadow {',
    '  readonly offsetX: number;',
    '  readonly offsetY: number;',
    '  readonly blurRadius: number;',
    '  readonly color: string;',
    '}',
    '',
    'export interface ColorSchemeTheme {',
    '  readonly dark: boolean;',
    '  readonly colors: Readonly<Record<ColorToken, string>>;',
    '  readonly glass: {',
    '    readonly background: string;',
    '    readonly border: string;',
    '    readonly blur: number;',
    '  };',
    '  readonly elevation: Shadow | null;',
    '}',
    '',
    tsConst('lightTheme', scheme('light'), '', 'ColorSchemeTheme'),
    tsConst('darkTheme', scheme('dark'), '', 'ColorSchemeTheme'),
    tsConst('space', t.space),
    tsConst('radius', t.radius),
    tsConst('touchTarget', t.touchTarget, ''),
    '/** Family name only; React Native has no fallback stack, the system font is the fallback. */',
    tsConst('fontFamily', familyName(t.font.family), ''),
    tsConst('typography', typography),
    tsConst('motion', t.motion),
  ].join('\n');
}

// ---------------------------------------------------------------------------------------------

if (import.meta.main) {
  for (const [path, content] of generate(readTokens())) {
    const target = join(PACKAGE_DIR, path);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, content);
    console.log(`wrote ${path}`);
  }
}
